final class SC_Lab_Exploratory_Data_Analysis_Studio_V01200 {
 const VERSION='0.120.0'; const ENGINE_VERSION='4.0.0'; const SCHEMA='sc-lab-exploratory-data-analysis-studio/0.120.0';
