 public static function manifest(){return rest_ensure_response(array('ok'=>true,'status'=>'exploratory-data-analysis-studio-ready','version'=>self::VERSION,'engineVersion'=>self::ENGINE_VERSION,'sourceRowsImmutable'=>true,'descriptiveStatistics'=>true,'missingnessAnalysis'=>true,'distributionAnalysis'=>true,'correlationAnalysis'=>true,'groupComparison'=>true,'robustOutlierFlags'=>true,'transformationPreview'=>true,'pcaExploration'=>true,'reproducibleSnapshots'=>true,'publicationVisualPlans'=>true,'automaticSourceMutation'=>false,'automaticHypothesisConfirmation'=>false,'automaticSignificanceClaims'=>false,'automaticCausalInference'=>false,'automaticScientificValidityCertification'=>false,'automaticCoreSubmission'=>false,'determineTruth'=>false));}
 public static function health(){ $req=array('contracts/exploratory-data-analysis-studio-v01200.schema.json','contracts/exploratory-data-analysis-studio-policy-v01200.json','includes/class-sc-lab-exploratory-data-analysis-studio-v01200.php','assets/js/modules/exploratory-data-analysis-studio-v01200.js','assets/css/sc-lab-exploratory-data-analysis-studio-v01200.css');$files=array();$ok=true;foreach($req as $r){$files[$r]=self::state($r);if(empty($files[$r]['exists']))$ok=false;}return rest_ensure_response(array('ok'=>$ok,'status'=>$ok?'exploratory-data-analysis-studio-ready':'incomplete','version'=>self::VERSION,'labReleaseVersion'=>defined('SC_LAB_RELEASE_VERSION')?SC_LAB_RELEASE_VERSION:self::VERSION,'engineVersion'=>self::ENGINE_VERSION,'analysisFamilyCount'=>9,'correlationMethodCount'=>2,'outlierMethodCount'=>3,'transformationCount'=>6,'apiRouteCount'=>20,'files'=>$files,'automaticSourceMutation'=>false,'automaticHypothesisConfirmation'=>false,'automaticScientificValidityCertification'=>false,'time'=>gmdate('c')));}
